            }
            sets.push({path: path + dirs[d], name: dirs[d].toLowerCase(), pack: pack});
        }
    }
    if (!onlyLocal) {
        try {
            dirs = fs.readdirSync(__dirname + '/../../../../');
            for (d = 0; d < dirs.length; d++) {
                if (dirs[d].match(/^iobroker\./i) && fs.existsSync(__dirname + '/../../../../' + dirs[d] + '/widgets/')) {
